from pathlib import Path
import json,html,hashlib,re
ROOT=Path(__file__).resolve().parent.parent
E=html.escape
for folder,study in [(ROOT/'elevations',False),(ROOT/'kitchen-dining-study/elevations',True)]:
 data=json.loads((folder/'elevation-schedule.json').read_text());plan=folder.parent/'approved-plan.svg'
 title='Approved compact kitchen + dining' if study else 'Earlier revision02 / living A — superseded'
 note=('Approved by the user on2026-11-09. Compact kitchen with north-wall fridge beside prep, sink under the window, west-wall pantry and dining between kitchen and sofa. This is the current design handoff.' if study else 'Historical elevation set, superseded by the approved compact kitchen/dining set in kitchen-dining-study/elevations. Do not use these older kitchen coordinates for integration.')
 pages=['<!doctype html><html><head><meta charset="utf-8"><style>body{margin:0;font-family:var(--font-sans,Arial,sans-serif);color:var(--foreground)}p{font-size:14px;line-height:1.5}select,button{font:inherit;background:var(--secondary);color:var(--foreground);border:1px solid var(--border);padding:8px 10px;border-radius:var(--radius,8px)}button{cursor:pointer}button.active{background:var(--primary);color:var(--primary-foreground)}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.hidden{display:none!important}.drawing{overflow:hidden;border-radius:var(--radius,8px)}img{display:block;width:100%;height:auto}.projection{display:none}.show-projection .projection{display:block}.show-projection .wall-only{display:none}.legend{columns:2;column-gap:24px;font-size:12px;line-height:1.5;padding:14px;background:var(--card);border-radius:var(--radius,8px);margin:12px 0}.legend div{break-inside:avoid;margin-bottom:6px}.quiet{color:var(--muted-foreground);font-size:12px}@media(max-width:500px){.legend{columns:1}}</style></head><body>']
 pages.append('<p>'+E(note)+'</p><div class="controls"><select id="room" aria-label="Drawing" onchange="show()"><option value="PLAN">Full floor plan</option>')
 for rid,(name,rect,color) in data['rooms'].items():pages.append(f'<option value="{rid}">{E(name)}</option>')
 pages.append('</select><span id="walls" class="hidden">')
 for side in 'NESW':pages.append(f'<button id="btn-{side}" onclick="side=\'{side}\';show()">{side}</button>')
 pages.append('</span><button id="projection" class="hidden" onclick="document.body.classList.toggle(\'show-projection\')">Toggle foreground furniture</button></div>')
 pages.append(f'<section class="sheet" id="PLAN"><div class="drawing"><img src="{plan}" alt="Full apartment floor plan"></div>')
 if study:pages.append('<p><strong>Dining:</strong> table rotated north–south, with1.24 m toward the kitchen and1.15 m toward the sofa. The small0.90 ×0.45 m kitchen wall table has a tucked stool.</p><p><strong>Window detail:</strong> kitchen sill1.25 m, head2.40 m, short apron and shallow sill. This is a new fitted window variant; the old export will not simply drop in.</p>')
 pages.append('</section>')
 for v in data['review']:
  pages.append(f'<section class="sheet hidden" id="{v["room"]}-{v["side"]}"><div class="drawing"><img class="wall-only" src="{folder/v["clean"]}" alt="{E(v["title"])}"><img class="projection" src="{folder/v["projected"]}" alt="{E(v["title"])} with furniture projections"></div><p>{E(v["notes"])}</p>')
  for cl,legend in [('wall-only',v['legend']),('projection',v['projection_legend'])]:
   pages.append(f'<div class="legend {cl}">'+''.join('<div>'+E(t)+'</div>' for t in legend)+'</div>')
  pages.append('</section>')
 pages.append('<p class="quiet">Elevations are schematic design drawings with source-asset IDs and dimensions. Faint foreground furniture is optional for clarity. No art exports, Unreal maps or gameplay were changed. Fit, motion and encounter-camera checks remain for integration.</p><script>let side="N";function show(){const room=document.getElementById("room").value;document.querySelectorAll(".sheet").forEach(e=>e.classList.add("hidden"));document.getElementById(room==="PLAN"?"PLAN":room+"-"+side).classList.remove("hidden");document.getElementById("walls").classList.toggle("hidden",room==="PLAN");document.getElementById("projection").classList.toggle("hidden",room==="PLAN");for(const s of ["N","E","S","W"])document.getElementById("btn-"+s).classList.toggle("active",s===side)}show();</script></body></html>')
 page_parts=re.split(r'(<[^>]+>)', ''.join(pages))
 page_clean=''.join(part if part.startswith('<') else re.sub(r'(?<=[A-Za-z×])(?=\d)', ' ', part) for part in page_parts)
 (folder/'review.html').write_text(page_clean)
 lines=[f'# {title} — elevation set','',note,'','## Drawings','', '[Interactive room/wall viewer](review.html). Each room has north, east, south and west views; individual wall SVGs also have a `-projected` version with floating/opposite-side furniture. Numbered markers refer to one physical assembly, even when it is visible in multiple views.','']
 for rid,(name,rect,color) in data['rooms'].items():lines.append(f'- [{name}: four-wall sheet]({rid.lower()}-elevations.svg)')
 lines+=['','## Surface and interaction design','','- Living, hall and bedroom: warm painterly plaster, original base/crown and honey wood floor. Bedroom has no wainscoting.','- Office/guest: white1.10 m wainscoting; interrupt panels and rail around window/apron, doors and wardrobe. Reuse BR-WAINSCOT-01 under its stable asset ID. The separate lead-paint condition is on the office north wall.','- Kitchen: muted sage cabinetry, cream enamel, restrained backsplash and warm checker floor. Worktops0.91 m; sink upstand1.135 m, faucet1.343 m. Cabinet frontages need fitted variants, not nonuniform scaling of hardware.','- Bathroom: pink tile with cream grout, localized Tyler damage; preserve the tub, fixtures, water reveal and operable parked curtain.','- Bedroom closet: mold stays on north interior back wall, with a single bulb and clear standing space. Doors conceal it. Coat and guest closets are separate, back-to-back reach-in storage.','- Damaged/repaired study SVGs: [mold closet](bc-n-repaired.svg), [office paint](of-n-repaired.svg), [bath tile](ba-s-repaired.svg). These depict removal of localized damage, not new gameplay implementation.','','## Construction and export notes','','- Door wall cuts allow3 cm per side beyond clear frame width, with rough heads2.14 m; sliders2.18 m. New room/entry door widths require matching frame/leaf variants. Closet pair uses1.10 m rough and1.00 m clear target.','- Wainscoting projects up to0.072 m; finish/casing/trim clearances must be deducted in engine. Floor-plan figures are planning values.','- Rebuild the larger bedroom closet shell and paired doors; fit the two smaller storage shells around their shared wall, avoiding duplicate geometry.','- Future moving exports should include UCX collision. Re-imports currently need the integration team’s collision script; see the durable integration handoff.','- Source front-axis conversion is not identical across kits. Plan-facing directions control placement; use the verified imported sofa +Y front.','- All static scene items and mounted dressing have physical records in [elevation-schedule.json](elevation-schedule.json). Some child props remain candidates or reuse existing geometry with distinct artwork; inclusion is not a claim of production readiness.','','## Review and limits','','- SVG parsing, opening extents and coverage of every scheduled assembly were checked. Footprint checks cover primary routes in the matching floor-plan JSON.','- The clean sheets show walls and nearby furniture; the projected sheets also show the floating sofa, table and opposite-wall pieces. An object repeated across views is not an instruction to duplicate it.','- No Unreal editor, source mesh, export, material or map was modified. These drawings require dimensional/collision/lighting validation during integration.','- Do not re-open an obsolete A+ elevation for placement. Use this set together with its matching revision floor plan.','']
 if study:lines+=['## New kitchen/dining fit requirements','','- Kitchen width4.80 m; partition x=4.80, portal y=2.35–3.55. Bookcase follows partition. Living A seating is unchanged.','- North sink centred x=2.15; aperture1.60 m wide, sill1.25/head2.40. Short apron bottom>=1.18 m; sill projection<=0.12 m from finished wall. Check faucet at1.343 m against glass/sash in depth.','- Fridge faces south beside north prep, at x=0.35 with0.29 m to west wall face and0.08 m to prep. Prep frontage is0.425 m; pantry remains west facing east. Nominal105-degree fridge sweep needs3D hardware/shelf validation. The east-return upper remains full-size1.00 m; check doors at the corner, with no cupboard directly above burners.','- Optional wall table0.90 ×0.45 m and tucked stool are new pieces; do not squash the vintage dining table to make them.','- Kitchen radiator from the earlier window wall is omitted in this alternative; any needed heating provision belongs to the later service/layout pass.','- Dining chairs pull north/south; keep both side aisles clear. A0.40 m south-chair pullback leaves0.40 m to the route centreline, which still needs capsule verification.','']
 (folder/'README.md').write_text(re.sub(r'(?<=[A-Za-z])(?=\d)', ' ', '\n'.join(lines))+'\n')
 # Every unique source/candidate ID including children with formal IDs.
 assets={}
 for o in data['items']:
  assets.setdefault(o['asset'],[]).append(o['name']+' ('+'/'.join(o['rooms'])+')')
  for child in o['children']:
   if '-' in child and child.upper()==child:assets.setdefault(child,[]).append('child of '+o['name'])
 for c in data['ceiling_fixtures']:assets.setdefault(c['asset'],[]).append('ceiling '+c['room'])
 for a in ['ARC-FLOOR-WOOD-01','KI-TILE-01','BA-FLOOR-01','ARC-TRIM-01','ARC-CEILING-PLASTER-01','LV-RUG-01','HA-RUNNER-01','BA-MAT-01','ARC-CURTAINS-01']:assets.setdefault(a,[]).append('surface / textile; see floor plan')
 md=['# Asset and finish handoff','','This is the drawing schedule, not an export-readiness list. Inspect the production log and each source README before importing.','','| Asset / candidate ID | Drawing uses |','|---|---|']
 for a,uses in sorted(assets.items()):md.append('| '+a+' | '+'; '.join(dict.fromkeys(uses))+' |')
 (folder/'Asset schedule.md').write_text('\n'.join(md)+'\n')
 print(title,': viewer, notes and',len(assets),'unique asset/finish references saved.')
